{"version":3,"sources":["../scss/profile_dialogs.scss","profile_dialogs.css","../scss/_variables.scss","../scss/_mixins.scss"],"names":[],"mappings":"AAGA;EACE,6BAAA;ACFF;;ADOA;EACE,gBAAA;EACA,iBAAA;EACA,iBAAA;EACA,QAAA;EACA,aAAA;EACA,sBAAA;ACJF;;ADOA;EACE,qBAAA;EACA,gCAAA;ACJF;;ADOA;EACE,aAAA;EACA,mBAAA;EACA,kBAAA;EACA,SAAA;ACJF;ADME;EACE,YE7BW;ADyBf;;ADQA;EACE,eAAA;EACA,eAAA;ACLF;ADME;EACE,WAAA;EACA,YAAA;EACA,gBAAA;EACA,sBAAA;KAAA,mBAAA;ACJJ;;ADSA;EACE,eAAA;EACA,aAAA;EACA,sBAAA;EACA,SAAA;ACNF;;ADSA;EGpDI,uCAAA;EACA,gBHoDkC;EGnDlC,kBAAA;EACA,YDHW;ECIX,eHiD4B;EAC9B,gBAAA;EACA,oBAAA;EACA,qBAAA;EACA,4BAAA;ACFF;;ADKA;EG5DI,uCAAA;EACA,gBH4D4B;EG3D5B,kBAAA;EACA,cH0Da;EGzDb,eHyDsB;ACE1B;;ADCA;EACE,WAAA;EACA,YAAA;EACA,kBAAA;EACA,QAAA;EACA,UAAA;EACA,eAAA;ACEF;;ADCA;EACE,yBAAA;EACA,kBAAA;ACEF","file":"profile_dialogs.css","sourcesContent":["@import \"./variables\";\n@import \"./mixins\";\n\n.main__info {\n  border-top: 1px solid $gray;\n}\n\n\n\n.chat__list {\n  overflow-y: auto;\n  max-height: 550px;\n  padding-top: 10px;\n  gap: 5px;\n  display: flex;\n  flex-direction: column;\n}\n\n.chat__list-item-wrap {\n  padding: 5px 0 10px 0;\n  border-bottom: 1px solid $gray;\n}\n\n.chat__list-item {\n  display: flex;\n  align-items: center;\n  position: relative;\n  gap: 20px;\n\n  &:hover {\n    color: $defaultColor;\n  }\n}\n\n.chat__list-img {\n  padding: 10px 0;\n  flex: 0 0 120px;\n  & img {\n    width: 100%;\n    height: 100%;\n    max-height: 80px;\n    object-fit: contain;\n\n  }\n}\n\n.chat__list-text {\n  padding: 10px 0;\n  display: flex;\n  flex-direction: column;\n  gap: 10px\n}\n\n.chat__list-text-title {\n  @include fonts($defaultColor, 20px, 400);\n  overflow: hidden;\n  display: -webkit-box;\n  -webkit-line-clamp: 1;\n  -webkit-box-orient: vertical;\n}\n\n.chat__list-text-last-message {\n  @include fonts(#A9A9A9, 16px, 400);\n}\n\n.cross__dialog {\n  width: 20px;\n  height: 20px;\n  position: absolute;\n  top: 5px;\n  right: 5px;\n  cursor: pointer;\n}\n\n.unread {\n  background-color: #F0F8FF;\n  border-radius: 7px;\n}\n",".main__info {\n  border-top: 1px solid #D4D4D4;\n}\n\n.chat__list {\n  overflow-y: auto;\n  max-height: 550px;\n  padding-top: 10px;\n  gap: 5px;\n  display: flex;\n  flex-direction: column;\n}\n\n.chat__list-item-wrap {\n  padding: 5px 0 10px 0;\n  border-bottom: 1px solid #D4D4D4;\n}\n\n.chat__list-item {\n  display: flex;\n  align-items: center;\n  position: relative;\n  gap: 20px;\n}\n.chat__list-item:hover {\n  color: black;\n}\n\n.chat__list-img {\n  padding: 10px 0;\n  flex: 0 0 120px;\n}\n.chat__list-img img {\n  width: 100%;\n  height: 100%;\n  max-height: 80px;\n  object-fit: contain;\n}\n\n.chat__list-text {\n  padding: 10px 0;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.chat__list-text-title {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 20px;\n  overflow: hidden;\n  display: -webkit-box;\n  -webkit-line-clamp: 1;\n  -webkit-box-orient: vertical;\n}\n\n.chat__list-text-last-message {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: #A9A9A9;\n  font-size: 16px;\n}\n\n.cross__dialog {\n  width: 20px;\n  height: 20px;\n  position: absolute;\n  top: 5px;\n  right: 5px;\n  cursor: pointer;\n}\n\n.unread {\n  background-color: #F0F8FF;\n  border-radius: 7px;\n}","$mainColor: #3077a0;\n$defaultColor: black;\n$colorHover: red;\n$headerTopBorder: #bdd4e2;\n$buttonBg:linear-gradient(0deg, #4d95d6,#6e93dd,#c2d6f4);;\n$gray: #D4D4D4;\n$vipBg: #ff6163;\n$activeItem: #FFFFCA;\n$userSearchBg: #CFE6FE;\n$asideLinksColor: #307792;\n$asideExitColor: rgb(0, 128, 0);","@mixin fonts($color,$size,$weight) {\n    font-family: 'Trebuchet MS', sans-serif;\n    font-weight: $weight;\n    font-style: normal;\n    color: $color;\n    font-size: $size;\n}"]}}